import { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../context/AuthContext";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [totp, setTotp] = useState("");
  const [error, setError] = useState("");
  const [requireTotp, setRequireTotp] = useState(false); // <-- new
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const res = await api.post("/auth/login", { email, password, totp: requireTotp ? totp : undefined });
      const { token, user } = res.data;

      login({ token, user });

      // Role-based redirect
      if (user.role === "student") {
        if (user.approved) {
          navigate("/candidates");
        } else {
          navigate("/pending-approval");
        }
      } else if (user.role === "admin") {
        navigate("/admin-dashboard");
      } else if (user.role === "comelec") {
        navigate("/comelec-dashboard");
      } else {
        navigate("/");
      }
    } catch (err) {
      // If server responds that TOTP is required
      if (err.response?.data?.error === "TOTP code required") {
        setRequireTotp(true); // show TOTP input
        setError("Enter your TOTP code to proceed");
      } else {
        setError(err.response?.data?.error || "Login failed");
      }
    }
  };

  return (
    <div className="flex items-center justify-center h-screen bg-gray-100">
      <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl shadow-md w-96">
        <h1 className="text-xl font-bold mb-4">Login</h1>
        {error && <p className="text-red-600 mb-2">{error}</p>}

        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="w-full p-2 mb-3 border rounded"
          required
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="w-full p-2 mb-3 border rounded"
          required
        />

        {requireTotp && (  // <-- only show if required
          <input
            type="text"
            placeholder="TOTP Code"
            value={totp}
            onChange={(e) => setTotp(e.target.value)}
            className="w-full p-2 mb-3 border rounded text-center"
            required
          />
        )}

        <button
          type="submit"
          className="w-full bg-blue-600 text-white py-2 rounded-xl hover:bg-blue-700"
        >
          Login
        </button>
      </form>
    </div>
  );
}
